	wg.Add(1)
	go func(id int) {
		defer wg.Done()
		for job := range jobs {
			// Simulate some work
			time.Sleep(time.Millisecond)

			// Fix 1: Race Condition
			atomic.AddInt32(&processedCount, 1)

			// Send result
			results <- Result{JobID: job.ID, Val: job.ID * 2}
		}
	}(i)
}

// Send jobs
go func() {
	for i := 0; i < numJobs; i++ {
		jobs <- Job{ID: i}
	}
	close(jobs)
}()

// Wait for all workers to finish processing jobs
wg.Wait()
close(results) // Close results channel AFTER all workers are done sending.

// Consume results in a separate goroutine
resultsWG.Add(1)
go func() {
	defer resultsWG.Done()
	for range results {
		// Just drain the channel
	}
}()

// Wait for results to be consumed
resultsWG.Wait()

